<?php require dirname(__DIR__,2).'/app/admin_view.php';admin_header('media','Music media library'); ?>
<section class="panel"><h2>Customer uploads</h2><p class="muted">Play audio and video, preview artwork, download originals and manage filenames. Release attachments remain linked to their orders.</p><input class="input" id="media-search" aria-label="Search media" placeholder="Search filename, customer or order"><select id="media-kind" aria-label="Media type"><option value="">All media</option><option>audio</option><option>artwork</option><option>video</option></select><p id="media-status" role="status"></p><div id="media-library" class="library"></div></section>
<style>.library{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:18px;margin-top:20px}.library article{min-width:0;padding:20px;border:1px solid #ffffff20;border-radius:14px;background:#ffffff04}.library h3{overflow-wrap:anywhere}.library audio,.library video{width:100%;margin:16px 0}.library img{width:100%;max-height:220px;object-fit:contain;margin:16px 0;background:#0003;border-radius:10px}.library .toolbar{flex-wrap:wrap}</style>
<script>
let media=[],csrf='';const make=(tag,text)=>{const e=document.createElement(tag);if(text)e.textContent=text;return e};async function loadMedia(){try{const r=await fetch('/api/music-media.php?library=1',{cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error);media=d.files;csrf=d.csrf;draw()}catch(e){document.getElementById('media-status').textContent=e.message}}function draw(){const box=document.getElementById('media-library');box.replaceChildren();const search=document.getElementById('media-search').value.toLowerCase(),kind=document.getElementById('media-kind').value;const filtered=media.filter(f=>(!kind||f.kind===kind)&&[f.original_name,f.customer,f.order_id].join(' ').toLowerCase().includes(search));document.getElementById('media-status').textContent=filtered.length+' files';for(const f of filtered){const card=make('article'),url='/api/music-media.php?id='+encodeURIComponent(f.id);card.append(make('h3',f.original_name),make('p',(f.customer||'Customer')+' · '+f.kind+' · '+(f.bytes/1048576).toFixed(2)+' MB'),make('p',f.order_id?'Release order #'+f.order_id:'Awaiting release submission'));const preview=make(f.kind==='artwork'?'img':f.kind==='audio'?'audio':'video');preview.src=url+'&inline=1';if(f.kind==='artwork'){preview.alt=f.original_name;preview.loading='lazy'}else{preview.controls=true;preview.preload='none'}card.append(preview);const actions=make('div');actions.className='toolbar';const download=make('a','Download original');download.className='btn primary';download.href=url;const rename=make('button','Rename');rename.className='btn';rename.onclick=async()=>{const name=prompt('Filename',f.original_name);if(!name||name===f.original_name)return;try{const r=await fetch('/api/music-media.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({action:'rename',id:f.id,name})}),d=await r.json();if(!r.ok)throw Error(d.error);await loadMedia()}catch(e){document.getElementById('media-status').textContent=e.message}};actions.append(download,rename);card.append(actions);box.append(card)}}document.getElementById('media-search').oninput=draw;document.getElementById('media-kind').onchange=draw;loadMedia();
</script><?php admin_footer(); ?>